/*
**    date_trunc( UNIT, TIMESTRING )
**
** Truncate the timestring to the specified precision.
** UNIT can be: 'year', 'month', 'day', 'hour', 'minute', 'second'
**
** Examples:
**   date_trunc('hour', '2001-02-16 20:38:40') -> '2001-02-16 20:00:00'
**   date_trunc('day', '2023-10-27 15:00:00') -> '2023-10-27 00:00:00'
*/
static void dateTruncFunc(
  sqlite3_context *context,
  int argc,
  sqlite3_value **argv
){
  DateTime x;
  const char *zUnit;
  int unitLen;
  char zBuf[32];
  int Y, s;

  /* Validate argument count */
  if( argc!=2 ){
    sqlite3_value_error(context, "date_trunc() must have exactly 2 arguments");
    return;
  }

  /* Check for NULL inputs */
  if( sqlite3_value_type(argv[0])==SQLITE_NULL 
   || sqlite3_value_type(argv[1])==SQLITE_NULL ){
    sqlite3_result_null(context);
    return;
  }

  /* Extract unit */
  zUnit = (const char*)sqlite3_value_text(argv[0]);
  if( zUnit==0 ) return;
  unitLen = sqlite3Strlen30(zUnit);

  /* Normalize unit to lowercase and match */
  if( unitLen==4 && sqlite3StrICmp(zUnit, "year")==0 ){
    /* Truncate to year: set month=1, day=1, hour=0, min=0, sec=0 */
    if( isDate(context, 1, argv+1, &x) ) return;
    computeYMD_HMS(&x);
    x.M = 1;
    x.D = 1;
    x.h = 0;
    x.m = 0;
    x.s = 0.0;
  }else if( unitLen==5 && sqlite3StrICmp(zUnit, "month")==0 ){
    /* Truncate to month: set day=1, hour=0, min=0, sec=0 */
    if( isDate(context, 1, argv+1, &x) ) return;
    computeYMD_HMS(&x);
    x.D = 1;
    x.h = 0;
    x.m = 0;
    x.s = 0.0;
  }else if( unitLen==3 && sqlite3StrICmp(zUnit, "day")==0 ){
    /* Truncate to day: set hour=0, min=0, sec=0 */
    if( isDate(context, 1, argv+1, &x) ) return;
    computeYMD_HMS(&x);
    x.h = 0;
    x.m = 0;
    x.s = 0.0;
  }else if( unitLen==4 && sqlite3StrICmp(zUnit, "hour")==0 ){
    /* Truncate to hour: set min=0, sec=0 */
    if( isDate(context, 1, argv+1, &x) ) return;
    computeYMD_HMS(&x);
    x.m = 0;
    x.s = 0.0;
  }else if( unitLen==6 && sqlite3StrICmp(zUnit, "minute")==0 ){
    /* Truncate to minute: set sec=0 */
    if( isDate(context, 1, argv+1, &x) ) return;
    computeYMD_HMS(&x);
    x.s = 0.0;
  }else if( unitLen==6 && sqlite3StrICmp(zUnit, "second")==0 ){
    /* Truncate to second: no change */
    if( isDate(context, 1, argv+1, &x) ) return;
    computeYMD_HMS(&x);
    /* Keep original values */
  }else{
    /* Invalid unit */
    sqlite3_value_error(context, "date_trunc() invalid unit: must be "
                        "'year', 'month', 'day', 'hour', 'minute', or 'second'");
    return;
  }

  /* Recompute JD and format result */
  computeJD(&x);
  if( x.isError || !validJulianDay(x.iJD) ) return;

  /* Format as YYYY-MM-DD HH:MM:SS */
  Y = x.Y;
  if( Y<0 ) Y = -Y;
  zBuf[1] = '0' + (Y/1000)%10;
  zBuf[2] = '0' + (Y/100)%10;
  zBuf[3] = '0' + (Y/10)%10;
  zBuf[4] = '0' + (Y)%10;
  zBuf[5] = '-';
  zBuf[6] = '0' + (x.M/10)%10;
  zBuf[7] = '0' + (x.M)%10;
  zBuf[8] = '-';
  zBuf[9] = '0' + (x.D/10)%10;
  zBuf[10] = '0' + (x.D)%10;
  zBuf[11] = ' ';
  zBuf[12] = '0' + (x.h/10)%10;
  zBuf[13] = '0' + (x.h)%10;
  zBuf[14] = ':';
  zBuf[15] = '0' + (x.m/10)%10;
  zBuf[16] = '0' + (x.m)%10;
  zBuf[17] = ':';
  s = (int)x.s;
  zBuf[18] = '0' + (s/10)%10;
  zBuf[19] = '0' + (s)%10;
  zBuf[20] = 0;

  if( x.Y<0 ){
    zBuf[0] = '-';
    sqlite3_result_text(context, zBuf, 20, SQLITE_TRANSIENT);
  }else{
    sqlite3_result_text(context, &zBuf[1], 19, SQLITE_TRANSIENT);
  }
}


